articles.correctCode:
public class Main {
    public static void main(String[] args) {
        int level = 1;
        switch (level) {
            case 1:
                System.out.println("初學者");
                break;
            case 2:
                System.out.println("進階者");
                break;
            default:
                System.out.println("其他");
        }
    }
}

